"""Evidence-led ZAF case study, profile and bilingual engineering journal."""
import html,json,math,re
from pathlib import Path
D=json.loads((Path(__file__).resolve().parents[1]/'content/practice.json').read_text())
def esc(value):return html.escape(str(value),quote=True)
def word_count(blocks):
 return sum(len(re.findall(r'\w+',str(b.get('text',''))+' '+' '.join(map(str,b.get('items',[])))+' '+str(b.get('rows',[])))) for b in blocks)
def diagram(kind,lang):
 fr=lang=='fr'
 if kind=='architecture':
  title='Frontières et flux proposés' if fr else 'Proposed boundaries and flows'
  labels=([('Navigateur','Brouillons non transmis'),('API applicative','Droits et versions'),('PostgreSQL','État · audit · outbox'),('Notifications','Effets différés'),('Worker','Reprises et dédoublonnage'),('Reporting','Projections et fraîcheur')] if fr else [('Browser','Unsent drafts'),('Application API','Permissions and versions'),('PostgreSQL','State · audit · outbox'),('Notifications','Asynchronous effects'),('Worker','Retries and deduplication'),('Reporting','Projections and freshness')])
  coords=[(20,90),(340,90),(660,90),(20,300),(340,300),(660,300)]
  arrows='<path d="M260 140H330M580 140H650M780 190V245H460V290M340 350H270M580 350H650"/>'
  desc=('Le navigateur transmet à l’API qui valide une transaction PostgreSQL. Le worker lit la boîte d’envoi et traite notifications et reporting. Schéma logique simplifié : identité, pièces jointes et sauvegardes sont hors du dessin.' if fr else 'The browser calls the API, which commits a PostgreSQL transaction. The worker reads the outbox and handles notifications and reporting. Simplified logical diagram; identity, attachments and backups are outside this drawing.')
 else:
  title='Décision et effets différés' if fr else 'Decision and asynchronous effects'
  labels=([('Commande','Acteur · clé · version'),('Contrôle serveur','Droits · état · version'),('Validation atomique','Décision · audit · outbox'),('Refus explicite','Aucun changement métier'),('Traitement différé','Reprises idempotentes')] if fr else [('Command','Actor · key · version'),('Server checks','Authority · state · version'),('Atomic commit','Decision · audit · outbox'),('Explicit rejection','No business state change'),('Asynchronous work','Idempotent retries')])
  coords=[(20,70),(340,70),(660,70),(340,290),(660,290)]
  arrows='<path d="M260 120H330M580 120H650M460 170V280M780 170V280"/>'
  desc=('Une commande valide est enregistrée atomiquement ; une commande non autorisée ou périmée est refusée. Les notifications sont traitées après validation et peuvent être reprises.' if fr else 'A valid command is committed atomically; an unauthorized or stale command is rejected. Notifications are processed after commit and may be retried.')
 boxes=''
 for i,((x,y),(name,sub)) in enumerate(zip(coords,labels)):
  boxes+=f'<g><rect x="{x}" y="{y}" width="240" height="100" rx="7" class="diagram-box"/><text x="{x+16}" y="{y+38}" class="diagram-name">{esc(name)}</text><text x="{x+16}" y="{y+68}" class="diagram-sub">{esc(sub)}</text></g>'
 return f'<figure class="zaf-diagram"><div class="diagram-scroll" tabindex="0" role="region" aria-label="{esc(title)}"><svg viewBox="0 0 920 430" role="img" aria-labelledby="{kind}-title {kind}-desc"><title id="{kind}-title">{esc(title)}</title><desc id="{kind}-desc">{esc(desc)}</desc><defs><marker id="{kind}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 10 5 0 10z" fill="currentColor"/></marker></defs><g fill="none" stroke="currentColor" stroke-width="2" marker-end="url(#{kind}-arrow)">{arrows}</g>{boxes}</svg></div><figcaption>{esc(desc)}</figcaption></figure>'
def blocks(items,lang):
 out=[]
 for b in items:
  kind=b['type']
  if kind=='p':out.append('<p>'+esc(b['text'])+'</p>')
  elif kind=='h2':out.append('<h2>'+esc(b['text'])+'</h2>')
  elif kind=='note':out.append('<aside class="method-note">'+esc(b['text'])+'</aside>')
  elif kind=='list':out.append('<ul>'+''.join('<li>'+esc(x)+'</li>' for x in b['items'])+'</ul>')
  elif kind=='code':out.append('<pre><code>'+esc(b['text'])+'</code></pre>')
  elif kind=='table':
   out.append('<div class="table-scroll" tabindex="0" role="region" aria-label="'+('Tableau de comparaison' if lang=='fr' else 'Comparison table')+'"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in b['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+esc(x)+'</th>') if i==0 else ('<td>'+esc(x)+'</td>') for i,x in enumerate(row))+'</tr>' for row in b['rows'])+'</tbody></table></div>')
  elif kind=='diagram':out.append(diagram(b['kind'],lang))
  elif kind=='links':out.append('<h2>'+('Références techniques' if lang=='fr' else 'Technical references')+'</h2><ul>'+''.join('<li><a href="'+esc(url)+'" rel="noopener noreferrer">'+esc(name)+'</a></li>' for name,url in b['items'])+'</ul>')
 return ''.join(out)
def case_teaser(lang,link):
 fr=lang=='fr';x=D['case'][lang]
 return '<div class="case-feature"><div><p class="eyebrow">ZAF / '+('ÉTUDE ILLUSTRATIVE' if fr else 'WORKED EXAMPLE')+'</p><h2>'+esc(x['title'])+'</h2><p>'+esc(x['summary'])+'</p>'+link('zaf/case-study/',('Examiner les décisions ↗' if fr else 'Examine the decisions ↗'),'solid')+'</div><aside><span class="case-number">01</span><h3>'+('Une décision explicable.' if fr else 'A decision you can explain.')+'</h3><p>'+('9 étapes · 2 schémas · 4 décisions d’architecture' if fr else '9 stages · 2 diagrams · 4 architecture decisions')+'</p><p class="fine">'+('Institution fictive. Hypothèses et preuves attendues clairement distinguées.' if fr else 'Fictional institution. Assumptions and required evidence are clearly distinguished.')+'</p></aside></div>'
def journal_cards(lang,link):
 fr=lang=='fr';out=[]
 for a in D['articles']:
  x=a[lang];minutes=max(1,math.ceil(word_count(x['blocks'])/200))
  out.append('<article class="article-card" data-category="'+esc(a['category'])+'" data-search="'+esc(x['title']+' '+a['category'])+'">'+link('blog/'+a['slug']+'/', '<div class="article-art tone-0"><span>'+('ÉTUDE TECHNIQUE' if fr else esc(a['cover']))+'</span><small>ZAWATU / ENGINEERING</small></div><p class="article-meta">'+esc(a['category'])+'</p><h3>'+esc(x['title'])+'</h3><p>'+esc(x['summary'])+'</p><p class="card-byline">Zawatu Editorial · 5 Nov 2026 · '+str(minutes)+' min</p><span class="read">'+('Lire l’analyse ↗' if fr else 'Read the analysis ↗')+'</span>')+'</article>')
 return '<div class="articles advanced-journal">'+''.join(out)+'</div>'
def profile_evidence(lang,link):
 fr=lang=='fr'
 timeline=([('EXPÉRIENCE · 2020','Mados Group','Ingénierie logicielle','Une première expérience professionnelle en développement logiciel, à la base de mon parcours d’ingénieur.'),('EXPÉRIENCE · 2023','Africonsnet','Ingénierie logicielle et gestion de projet','Un travail associant réalisation technique et coordination de projet, avec une attention portée aux besoins métier et à la livraison.'),('ENTREPRENEURIAT','Smart Data Services','Fondateur · Entreprise de développement logiciel','J’ai fondé Smart Data Services pour exercer une activité d’entreprise dans le logiciel. Cette expérience relie réalisation technique, responsabilité de livraison et relation client.'),('PRATIQUE ACTUELLE','Zawatu','Fondateur · Consultant indépendant','Zawatu porte ma pratique de conseil et mon développement professionnel : aider les institutions à comprendre leurs systèmes, structurer leurs données et préparer des décisions d’architecture.')] if fr else [('EXPERIENCE · 2020','Mados Group','Software engineering','An early professional foundation in software development that shaped my engineering career.'),('EXPERIENCE · 2023','Africonsnet','Software engineering & project management','Work combining technical delivery and project coordination, connecting business requirements with implementation.'),('ENTREPRENEURSHIP','Smart Data Services','Founder · Software company','I founded Smart Data Services as a software business. That experience connects engineering work with delivery responsibility and client relationships.'),('CURRENT PRACTICE','Zawatu','Founder · Independent consultant','Zawatu is the home of my consulting practice and professional development: helping institutions understand their systems, structure their data and prepare architecture decisions.')])
 body='<div class="profile-evidence"><div class="profile-intro"><span class="eyebrow">'+('PARCOURS PROFESSIONNEL' if fr else 'PROFESSIONAL BACKGROUND')+'</span><h2>'+('Du développement logiciel au conseil en architecture.' if fr else 'From software delivery to architecture consulting.')+'</h2><p>'+('Mon parcours associe emploi, entrepreneuriat logiciel et conseil indépendant. Zawatu donne une direction précise à cette expérience : relier les besoins institutionnels à une ingénierie cohérente et exploitable.' if fr else 'My background spans employed engineering work, software entrepreneurship and independent consulting. Zawatu gives that experience a focused direction: connecting institutional needs with coherent, operable engineering.')+'</p></div><div class="career-timeline professional-timeline">'+''.join('<article><span class="eyebrow">'+esc(stage)+'</span><h3>'+esc(org)+'</h3><p><strong>'+esc(role)+'</strong></p><p>'+esc(desc)+'</p></article>' for stage,org,role,desc in timeline)+'</div>'
 body+='<div class="review-grid"><div><span class="eyebrow">'+('POURQUOI ZAWATU' if fr else 'WHY ZAWATU')+'</span><h2>'+('Aider les institutions à comprendre avant de construire.' if fr else 'Help institutions understand before they build.')+'</h2><p>'+('Une institution ne se résume pas à ses applications. Ses services dépendent de responsabilités, de règles, de données, d’intégrations et d’équipes capables d’agir ensemble. Mon rôle est de rendre ces liens explicites pour guider conception, réalisation et évolution.' if fr else 'An institution is more than its applications. Its services depend on responsibilities, rules, data, integrations and teams that can work together. My role is to make those connections explicit so they can guide design, delivery and change.')+'</p><p>'+('Basé au Burundi, je construis cette pratique dans une perspective régionale et internationale, avec une attention particulière aux contraintes réelles de capacité, de connectivité et d’exploitation.' if fr else 'Based in Burundi, I am building this practice with a regional and international outlook, attentive to real constraints in capacity, connectivity and operations.')+'</p></div><div><h2>'+('Une pratique, des livrables précis.' if fr else 'A focused practice. Concrete deliverables.')+'</h2><p>'+('Les missions peuvent porter sur une revue de l’existant, une conception d’architecture, des contrats de données, une réalisation backend ou la préparation opérationnelle d’une plateforme. Périmètre, accès, responsabilités et honoraires sont définis avant démarrage.' if fr else 'Engagements can cover a current-state review, architecture design, data contracts, backend implementation or platform readiness. Scope, access, responsibilities and fees are agreed before work begins.')+'</p><p>'+('Les technologies viennent après les exigences. Je privilégie les décisions documentées, les compromis explicites, les vérifications adaptées et le transfert de connaissances aux équipes.' if fr else 'Technology follows requirements. I prioritize documented decisions, explicit trade-offs, appropriate verification and knowledge transfer to the team.')+'</p>'+link('services/',('Explorer les domaines d’intervention ↗' if fr else 'Explore the consulting scope ↗'),'text-link')+'</div></div>'
 rows=([('Architecture des systèmes','Processus métier, responsabilités et intégrations','Cartographie de l’existant, options, décisions et feuille de route.'),('Ingénierie des données','API, PostgreSQL, modèles et reporting','Traçabilité, contrats de données, contrôles qualité et rapprochement.'),('Ingénierie logicielle','Services backend, autorisations et workflows','Frontières métier, contrats API et scénarios de cohérence.'),('Plateformes et DevOps','Conteneurs, CI/CD et livraison cloud','Déploiements reproductibles, observabilité, reprise et transfert.'),('Fondations pour l’IA','Qualité, provenance et disponibilité des données','Examiner la préparation des données avant de proposer un usage de l’IA.')] if fr else [('Systems architecture','Business processes, responsibilities and integrations','Current-state maps, options, decisions and phased roadmaps.'),('Data engineering','APIs, PostgreSQL, models and reporting','Lineage, data contracts, quality checks and reconciliation.'),('Software engineering','Backend services, authorization and workflows','Domain boundaries, API contracts and consistency scenarios.'),('Platforms & DevOps','Containers, CI/CD and cloud delivery','Repeatable releases, observability, recovery and handover.'),('Foundations for AI','Data quality, provenance and availability','Assess data readiness before proposing an AI use case.')])
 body+='<h2>'+('Comment cette expérience sert une mission' if fr else 'How this experience informs an engagement')+'</h2>'+blocks([dict(type='table',headers=(['Domaine','Expérience et pratique mobilisées','Livrables possibles'] if fr else ['Area','Experience and practice applied','Potential deliverables']),rows=rows)],lang)
 body+='<div class="profile-intro"><h2>'+('ZAF : documenter une pensée d’architecture.' if fr else 'ZAF: making architecture thinking inspectable.')+'</h2><p>'+('Je développe le Zawatu Architecture Framework comme une bibliothèque vivante de huit livres, de l’architecture institutionnelle aux standards, à la réalisation et à l’exploitation. Les sections sont publiées progressivement avec leurs statuts, hypothèses et critères de revue. C’est un travail en développement, sans certification ni adoption externe revendiquée.' if fr else 'I am developing the Zawatu Architecture Framework as a living eight-book library, spanning institutional architecture, standards, implementation and operations. Sections are published progressively with their status, assumptions and review criteria. It is work in development, with no claim of certification or external adoption.')+'</p>'+link('zaf/',('Lire la bibliothèque ZAF ↗' if fr else 'Read the ZAF library ↗'),'text-link')+'</div>'
 body+='<h2>'+('Travaux à examiner' if fr else 'Work you can examine')+'</h2><div class="evidence-grid">'
 cards=([('Bibliothèque et étude ZAF','Les chapitres expliquent la démarche ; l’étude fictive montre son application et ses limites. Elle ne constitue pas une référence client.','zaf/','Explorer ZAF ↗'),('Réalisation et livraison','Le dépôt de ce site montre son générateur, ses contrôles et son workflow de publication, dans ce périmètre précis.','https://github.com/elvisquant/zawatu','Voir le dépôt ↗'),('Journal d’ingénierie','Des analyses sur la cohérence, les contrats de reporting et la préparation des plateformes.','blog/','Lire le journal ↗')] if fr else [('ZAF library and worked study','Chapters explain the method; the fictional study demonstrates its application and limits. It is not a client reference.','zaf/','Explore ZAF ↗'),('Implementation and delivery','This website’s repository shows its generator, checks and publication workflow within that specific scope.','https://github.com/elvisquant/zawatu','Inspect the repository ↗'),('Engineering journal','Substantial analysis of consistency, reporting contracts and platform readiness.','blog/','Read the journal ↗')])
 for title,desc,url,label in cards:
  target=('<a class="text-link" href="'+esc(url)+'" rel="noopener noreferrer">'+label+'</a>') if url.startswith('https:') else link(url,label,'text-link')
  body+='<article><h3>'+title+'</h3><p>'+desc+'</p>'+target+'</article>'
 body+='</div><p class="fine">'+('Les missions institutionnelles et documents clients sont présentés uniquement avec autorisation de divulgation. Les ressources publiques permettent d’examiner la méthode et le travail qu’elles documentent.' if fr else 'Institutional engagements and client documents are discussed only where disclosure is authorized. Public resources let you examine the method and the work they actually document.')+'</p></div>'
 return body
def publish_deep_pages(lang,page,hero,section,link,cta):
 fr=lang=='fr';x=D['case'][lang]
 page('zaf/case-study/',x['title'],x['summary'],hero('ZAF / '+('ÉTUDE ILLUSTRATIVE' if fr else 'WORKED EXAMPLE'),esc(x['title']),esc(x['summary']))+section('<aside class="method-note">'+('Cette page résume le cas. Pour la bibliothèque ZAF : ' if fr else 'This page summarizes the case. For the living ZAF library: ')+link('zaf/',('ouvrir la documentation ZAF ↗' if fr else 'open the ZAF documentation ↗'),'text-link')+'</aside>')+section('<article class="case-study-body">'+blocks(x['blocks'],lang)+'</article>')+section('<h2>'+('Appliquer cette démarche à votre contexte' if fr else 'Apply this approach to your context')+'</h2><p>'+('La première mission examine un parcours, ses données et ses risques, puis fournit une cartographie et des recommandations priorisées. Le périmètre et les honoraires sont convenus avant le démarrage.' if fr else 'A starting engagement examines one workflow, its data and its risks, then produces a current-state map and prioritized recommendations. Scope and fees are agreed before work begins.')+'</p>'+link('contact/',('Discuter d’une revue ↗' if fr else 'Discuss an architecture review ↗'),'solid'),'soft'))
 for a in D['articles']:
  x=a[lang];minutes=max(1,math.ceil(word_count(x['blocks'])/200))
  body=hero('JOURNAL / '+a['category'],esc(x['title']),esc(x['summary']))
  body+=section('<p class="reading-meta">Zawatu Editorial · 5 Nov 2026 · '+str(minutes)+' min</p><article class="article-body longform">'+blocks(x['blocks'],lang)+'</article>')
  body+=section('<div class="article-next"><span class="eyebrow">'+('DE LA LECTURE À LA PRATIQUE' if fr else 'FROM ANALYSIS TO PRACTICE')+'</span><h2>'+('Voir ces décisions dans une architecture complète.' if fr else 'See these decisions in a complete architecture.')+'</h2>'+link('zaf/case-study/',('Explorer l’étude ZAF ↗' if fr else 'Explore the ZAF study ↗'),'text-link')+'<p>'+('Une revue peut appliquer ces questions à un périmètre concret de votre organisation.' if fr else 'An architecture review can apply these questions to a concrete part of your organization.')+'</p>'+link('contact/',('Présenter votre contexte ↗' if fr else 'Describe your context ↗'),'solid')+'</div>','soft')
  page('blog/'+a['slug']+'/',x['title'],x['summary'],body)
